def successor(self, x):
    """
    Return the smallest element greater than x in the tree.

    Args:
        x (int): Element to find successor for.

    Returns:
        int | None: Successor of x if exists, otherwise None.

    Raises:
        ValueError: If x is outside the universe.
    """
    self._validate_key(x)
    if self.u == 2:
        if x == 0 and self.max == 1:
            return 1
        return None

    if self.min is not None and x < self.min:
        return self.min

    high = self.high(x)
    low = self.low(x)

    max_low = self.cluster[high].max

    if max_low is not None and low < max_low:
        offset = self.cluster[high].successor(low)
        return self.index(high, offset)
    else:
        succ_cluster = self.summary.successor(high)
        if succ_cluster is None:
            return None
        offset = self.cluster[succ_cluster].min
        return self.index(succ_cluster, offset)

def delete(self, x):
    """
    Remove element x from the Van Emde Boas tree.

    Args:
        x (int): Element to delete.

    Raises:
        ValueError: If x is outside the universe.
    """
    self._validate_key(x)
    if self.min == self.max:
        self.min = self.max = None
        return

    if self.u == 2:
        if x == 0:
            self.min = 1
        else:
            self.min = 0
        self.max = self.min
        return

    if x == self.min:
        first_cluster = self.summary.min
        x = self.index(first_cluster, self.cluster[first_cluster].min)
        self.min = x

    high = self.high(x)
    low = self.low(x)
    self.cluster[high].delete(low)

    if self.cluster[high].min is None:
        self.summary.delete(high)

        if x == self.max:
            summary_max = self.summary.max
            if summary_max is None:
                self.max = self.min
            else:
                self.max = self.index(summary_max, self.cluster[summary_max].max)
    elif x == self.max:
        self.max = self.index(high, self.cluster[high].max)

def tsp(dist: list[list[float]]) -> float:
    """Return the minimum cost of a Hamiltonian cycle.

    *dist* is an n x n distance matrix.

    >>> tsp([[0, 10, 15, 20],
    ...      [10, 0, 35, 25],
    ...      [15, 35, 0, 30],
    ...      [20, 25, 30, 0]])
    80
    """
    n = len(dist)
    full_mask = (1 << n) - 1
    dp: dict[tuple[int, int], float] = {}

    def solve(mask: int, pos: int) -> float:
        if mask == full_mask:
            return dist[pos][0]
        key = (mask, pos)
        if key in dp:
            return dp[key]
        ans = math.inf
        for city in range(n):
            if not (mask & (1 << city)):
                ans = min(ans, dist[pos][city] + solve(mask | (1 << city), city))
        dp[key] = ans
        return ans

    return solve(1, 0)

def solve(mask: int, pos: int) -> float:
    if mask == full_mask:
        return dist[pos][0]
    key = (mask, pos)
    if key in dp:
        return dp[key]
    ans = math.inf
    for city in range(n):
        if not (mask & (1 << city)):
            ans = min(ans, dist[pos][city] + solve(mask | (1 << city), city))
    dp[key] = ans
    return ans

def count_paths_recursive(m: int, n: int) -> int:
    """Naive recursive solution — O(2^(m+n))."""
    if m == 1 or n == 1:
        return 1
    return count_paths_recursive(m - 1, n) + count_paths_recursive(m, n - 1)

def count_paths_memo(m: int, n: int) -> int:
    """Top-down DP with memoization — O(m*n)."""

    @cache
    def helper(i: int, j: int) -> int:
        if i == 1 or j == 1:
            return 1
        return helper(i - 1, j) + helper(i, j - 1)

    return helper(m, n)

def helper(i: int, j: int) -> int:
    if i == 1 or j == 1:
        return 1
    return helper(i - 1, j) + helper(i, j - 1)

def hosoya(height: int, width: int) -> int:
    """Compute a single entry in the Hosoya triangle.

    Args:
        height: Row index (0-based).
        width: Column index (0-based).

    Returns:
        The value at position (height, width) in the Hosoya triangle.

    Examples:
        >>> hosoya(4, 2)
        4
    """
    if (width == 0) and (height in (0, 1)):
        return 1
    if (width == 1) and (height in (1, 2)):
        return 1
    if height > width:
        return hosoya(height - 1, width) + hosoya(height - 2, width)
    if width == height:
        return hosoya(height - 1, width - 1) + hosoya(height - 2, width - 2)
    return 0

def _binary_search(job: list[Job], start_index: int) -> int:
    """Find the latest non-conflicting job before start_index.

    Args:
        job: List of jobs sorted by finish time.
        start_index: Index of the current job.

    Returns:
        Index of the latest compatible job, or -1 if none exists.
    """
    left = 0
    right = start_index - 1

    while left <= right:
        mid = (left + right) // 2
        if job[mid].finish <= job[start_index].start:
            if job[mid + 1].finish <= job[start_index].start:
                left = mid + 1
            else:
                return mid
        else:
            right = mid - 1
    return -1

