def _factor(
    n: int,
    i: int,
    combi: list[int],
    res: list[list[int]],
) -> list[list[int]]:
    while i * i <= n:
        if n % i == 0:
            res += (combi + [i, int(n / i)],)
            _factor(n / i, i, combi + [i], res)
        i += 1
    return res

def bellman_ford(graph: dict[str, dict[str, float]], source: str) -> bool:
    """Compute shortest paths from *source* and detect negative cycles.

    Args:
        graph: Weighted directed graph as
            ``{node: {neighbor: edge_weight, ...}, ...}``.
        source: The starting vertex.

    Returns:
        True if shortest paths were computed (no negative cycle), False
        otherwise.

    Examples:
        >>> g = {'a': {'b': 1}, 'b': {'c': 2}, 'c': {}}
        >>> bellman_ford(g, 'a')
        True
    """
    distance: dict[str, float] = {}
    predecessor: dict[str, str | None] = {}

    _initialize_single_source(graph, source, distance, predecessor)

    num_vertices = len(graph)
    for _ in range(1, num_vertices):
        for current_node in graph:
            for neighbor in graph[current_node]:
                edge_weight = graph[current_node][neighbor]
                if distance[neighbor] > distance[current_node] + edge_weight:
                    distance[neighbor] = distance[current_node] + edge_weight
                    predecessor[neighbor] = current_node

    for current_node in graph:
        for neighbor in graph[current_node]:
            edge_weight = graph[current_node][neighbor]
            if distance[neighbor] > distance[current_node] + edge_weight:
                return False

    return True

def find_augmenting_path() -> bool:
    """Try to find an augmenting path from any free vertex."""
    parent = [-1] * n
    visited = [False] * n
    for start in range(n):
        if match[start] != -1:
            continue
        # BFS from this free vertex
        queue: deque[int] = deque([start])
        visited[start] = True
        found = False
        while queue and not found:
            u = queue.popleft()
            for v in adj[u]:
                if visited[v] or v == match[u]:
                    continue
                if match[v] == -1 and v != start:
                    # Augmenting path found — trace back and flip
                    _augment(parent, match, u, v)
                    return True
                if match[v] != -1:
                    visited[v] = True
                    visited[match[v]] = True
                    parent[match[v]] = u
                    queue.append(match[v])
    return False

