def _scc(graph: dict[Any, list[Any]]) -> dict[Any, int]:
    """Compute SCCs using Kosaraju's algorithm.

    Args:
        graph: Directed graph adjacency list.

    Returns:
        Mapping from vertex to its SCC index.
    """
    order: list[Any] = []
    visited = {vertex: False for vertex in graph}

    graph_transposed: dict[Any, list[Any]] = {vertex: [] for vertex in graph}

    for source, neighbours in graph.items():
        for target in neighbours:
            _add_edge(graph_transposed, target, source)

    for vertex in graph:
        if not visited[vertex]:
            _dfs_transposed(vertex, graph_transposed, order, visited)

    visited = {vertex: False for vertex in graph}
    vertex_scc: dict[Any, int] = {}

    current_comp = 0
    for vertex in reversed(order):
        if not visited[vertex]:
            _dfs(vertex, current_comp, vertex_scc, graph, visited)
            current_comp += 1

    return vertex_scc

def _build_graph(
    formula: list[tuple[tuple[str, bool], tuple[str, bool]]],
) -> dict[tuple[str, bool], list[tuple[str, bool]]]:
    """Build the implication graph from a 2-CNF formula.

    Args:
        formula: List of clauses, each a pair of literals
            ``(name, is_negated)``.

    Returns:
        Implication graph as an adjacency list.
    """
    graph: dict[tuple[str, bool], list[tuple[str, bool]]] = {}

    for clause in formula:
        for lit, _ in clause:
            for neg in [False, True]:
                graph[(lit, neg)] = []

    for (a_lit, a_neg), (b_lit, b_neg) in formula:
        _add_edge(graph, (a_lit, a_neg), (b_lit, not b_neg))
        _add_edge(graph, (b_lit, b_neg), (a_lit, not a_neg))

    return graph

def solve_sat(
    formula: list[tuple[tuple[str, bool], tuple[str, bool]]],
) -> dict[str, bool] | None:
    """Solve a 2-SAT formula.

    Args:
        formula: List of clauses in 2-CNF.

    Returns:
        A satisfying assignment as ``{variable: value}`` or None if
        unsatisfiable.

    Examples:
        >>> solve_sat([(('x', False), ('y', False)), (('x', True), ('y', True))])
        {'x': False, 'y': False}
    """
    graph = _build_graph(formula)
    vertex_scc = _scc(graph)

    for var, _ in graph:
        if vertex_scc[(var, False)] == vertex_scc[(var, True)]:
            return None

    comp_repr: dict[int, tuple[str, bool]] = {}

    for vertex in graph:
        if vertex_scc[vertex] not in comp_repr:
            comp_repr[vertex_scc[vertex]] = vertex

    comp_value: dict[int, bool] = {}
    components = sorted(vertex_scc.values())

    for comp in components:
        if comp not in comp_value:
            comp_value[comp] = False
            lit, neg = comp_repr[comp]
            comp_value[vertex_scc[(lit, not neg)]] = True

    value = {var: comp_value[vertex_scc[(var, False)]] for var, _ in graph}

    return value

def _possible_values(self) -> dict[tuple[int, int], list[str]]:
    """Compute possible values for each empty cell.

    Returns:
        Mapping from (row, col) to list of candidate digits.
    """
    a = "123456789"
    d: dict[tuple[str, int] | tuple[int, int], list[str]] = {}
    val: dict[tuple[int, int], list[str]] = {}
    for i in range(self.row):
        for j in range(self.col):
            ele = self.board[i][j]
            if ele != ".":
                d[("r", i)] = d.get(("r", i), []) + [ele]
                d[("c", j)] = d.get(("c", j), []) + [ele]
                d[(i // 3, j // 3)] = d.get((i // 3, j // 3), []) + [ele]
            else:
                val[(i, j)] = []
    for i, j in val:
        inval = (
            d.get(("r", i), []) + d.get(("c", j), []) + d.get((i / 3, j / 3), [])
        )
        val[(i, j)] = [n for n in a if n not in inval]
    return val

def solve(self) -> bool:
    """Attempt to solve the board in place.

    Returns:
        True if a solution was found.
    """
    if len(self.val) == 0:
        return True
    kee = min(self.val.keys(), key=lambda x: len(self.val[x]))
    nums = self.val[kee]
    for n in nums:
        update: dict[tuple[int, int], str | list[str]] = {kee: self.val[kee]}
        if self._valid_one(n, kee, update) and self.solve():
                return True
        self._undo(kee, update)
    return False

def _undo(
    self,
    kee: tuple[int, int],
    update: dict[tuple[int, int], str | list[str]],
) -> None:
    """Revert the placement at *kee* using *update*.

    Args:
        kee: (row, col) coordinate.
        update: Undo log.
    """
    self.board[kee[0]][kee[1]] = "."
    for k in update:
        if k not in self.val:
            self.val[k] = update[k]
        else:
            self.val[k].append(update[k])

def _dfs(node: str) -> None:
    state[node] = _GRAY
    for neighbour in graph.get(node, ()):
        neighbour_state = state.get(neighbour)
        if neighbour_state == _GRAY:
            raise ValueError("cycle")
        if neighbour_state == _BLACK:
            continue
        enter.discard(neighbour)
        _dfs(neighbour)
    order.append(node)
    state[node] = _BLACK

def _is_ready(node: str) -> bool:
    neighbours = graph.get(node, ())
    if len(neighbours) == 0:
        return True
    for neighbour in neighbours:
        neighbour_state = state.get(neighbour)
        if neighbour_state == _GRAY:
            raise ValueError("cycle")
        if neighbour_state != _BLACK:
            return False
    return True

def add_edge(self, source: int, target: int) -> None:
