def _dfs_util(self, source: int, target: int) -> None:
    """Recursive DFS marking reachability from *source* through *target*.

    Args:
        source: Origin vertex.
        target: Current vertex being explored.
    """
    self.closure[source][target] = 1

    for adjacent in self.graph[target]:
        if self.closure[source][adjacent] == 0:
            self._dfs_util(source, adjacent)

def walls_and_gates(rooms: list[list[int]]) -> None:
    """Fill *rooms* in place with distances to nearest gates.

    Args:
        rooms: 2D grid (-1 = wall, 0 = gate, INF = empty room).

    Examples:
        >>> r = [[float('inf'), 0]]; walls_and_gates(r); r
        [[1, 0]]
    """
    for i in range(len(rooms)):
        for j in range(len(rooms[0])):
            if rooms[i][j] == 0:
                _dfs(rooms, i, j, 0)

def _word_range(word: str) -> Iterator[str]:
    """Yield all words that differ from *word* by exactly one letter.

    Args:
        word: The source word.

    Yields:
        Words with a single character changed.
    """
    for ind in range(len(word)):
        temp = word[ind]
        for c in [chr(x) for x in range(ord("a"), ord("z") + 1)]:
            if c != temp:
                yield word[:ind] + c + word[ind + 1 :]

def gale_shapley(
    men: dict[str, list[str]],
    women: dict[str, list[str]],
) -> dict[str, str]:
    """Find a stable matching between men and women.

    Args:
        men: Mapping of each man to his preference list of women
            (highest to lowest).
        women: Mapping of each woman to her preference list of men
            (highest to lowest).

    Returns:
        A dict mapping each man to his matched woman.

    Examples:
        >>> men = {"M1": ["W1", "W2"], "M2": ["W1", "W2"]}
        >>> women = {"W1": ["M2", "M1"], "W2": ["M1", "M2"]}
        >>> sorted(gale_shapley(men, women).items())
        [('M1', 'W2'), ('M2', 'W1')]
    """
    men_available: list[str] = list(men.keys())
    married: dict[str, str] = {}
    proposal_counts: dict[str, int] = {man: 0 for man in men}

    while men_available:
        man = men_available.pop(0)
        woman = men[man][proposal_counts[man]]
        proposal_counts[man] += 1

        if woman not in married:
            married[woman] = man
        else:
            current_partner = married[woman]
            if women[woman].index(man) < women[woman].index(current_partner):
                married[woman] = man
                men_available.append(current_partner)
            else:
                men_available.append(man)

    return {man: woman for woman, man in married.items()}

