def is_valid_sudoku(board: list[list[str]]) -> bool:
    """Check whether a Sudoku board configuration is valid.

    Args:
        board: 9x9 grid where empty cells are represented by '.'.

    Returns:
        True if the board is valid, False otherwise.

    Examples:
        >>> is_valid_sudoku([['.' for _ in range(9)] for _ in range(9)])
        True
    """
    seen: list[tuple[str, ...]] = []
    for i, row in enumerate(board):
        for j, cell in enumerate(row):
            if cell != ".":
                seen += [(cell, j), (i, cell), (i // 3, j // 3, cell)]
    return len(seen) == len(set(seen))

def solve_chinese_remainder(nums: list[int], rems: list[int]) -> int:
    """Find the smallest x satisfying x % nums[i] == rems[i] for all i.

    Args:
        nums: List of pairwise coprime moduli, each greater than 1.
        rems: List of remainders corresponding to each modulus.

    Returns:
        The smallest positive integer satisfying all congruences.

    Raises:
        Exception: If inputs are invalid or moduli are not pairwise coprime.

    Examples:
        >>> solve_chinese_remainder([3, 7, 10], [2, 3, 3])
        143
    """
    if not len(nums) == len(rems):
        raise Exception("nums and rems should have equal length")
    if not len(nums) > 0:
        raise Exception("Lists nums and rems need to contain at least one element")
    for num in nums:
        if not num > 1:
            raise Exception("All numbers in nums needs to be > 1")
    if not _check_coprime(nums):
        raise Exception("All pairs of numbers in nums are not coprime")
    k = len(nums)
    x = 1
    while True:
        i = 0
        while i < k:
            if x % nums[i] != rems[i]:
                break
            i += 1
        if i == k:
            return x
        x += 1

def _check_coprime(list_to_check: list[int]) -> bool:
    """Check whether all pairs of numbers in the list are coprime.

    Args:
        list_to_check: List of integers to check for pairwise coprimality.

    Returns:
        True if all pairs are coprime, False otherwise.
    """
    for ind, num in enumerate(list_to_check):
        for num2 in list_to_check[ind + 1 :]:
            if gcd(num, num2) != 1:
                return False
    return True

def combination_memo(n: int, r: int) -> int:
    """Calculate nCr using memoization.

    Args:
        n: Total number of items.
        r: Number of items to choose.

    Returns:
        The number of combinations.

    Examples:
        >>> combination_memo(50, 10)
        10272278170
    """
    memo: dict[tuple[int, int], int] = {}

    def _recur(n: int, r: int) -> int:
        if n == r or r == 0:
            return 1
        if (n, r) not in memo:
            memo[(n, r)] = _recur(n - 1, r - 1) + _recur(n - 1, r)
        return memo[(n, r)]

    return _recur(n, r)

def _recur(n: int, r: int) -> int:
    if n == r or r == 0:
        return 1
    if (n, r) not in memo:
        memo[(n, r)] = _recur(n - 1, r - 1) + _recur(n - 1, r)
    return memo[(n, r)]

def _prime_check(num: int) -> bool:
    """Check whether a number is prime.

    Args:
        num: The integer to test.

    Returns:
        True if num is prime, False otherwise.
    """
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    j = 5
    while j * j <= num:
        if num % j == 0 or num % (j + 2) == 0:
            return False
        j += 6
    return True

def _find_order(a: int, n: int) -> int:
    """Find the multiplicative order of a modulo n.

    Args:
        a: The base integer.
        n: The modulus.

    Returns:
        The smallest positive k such that a^k = 1 (mod n), or -1 if none exists.
    """
    if (a == 1) & (n == 1):
        return 1
    if math.gcd(a, n) != 1:
        return -1
    for i in range(1, n):
        if pow(a, i) % n == 1:
            return i
    return -1

def _euler_totient(n: int) -> int:
    """Compute Euler's totient function phi(n).

    Args:
        n: A positive integer.

    Returns:
        The number of integers from 1 to n that are coprime with n.
    """
    result = n
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            while n % i == 0:
                n //= i
            result -= result // i
    if n > 1:
        result -= result // n
    return result

def _find_order(a: int, n: int) -> int:
